#include <bits/stdc++.h>
using namespace std;

int main(){
    auto startTime = chrono::steady_clock::now();

    string input((istreambuf_iterator<char>(cin)), istreambuf_iterator<char>());

    // Robust JSON parsing
    vector<tuple<string,int,long long,long long,long long>> items;
    size_t pos = input.find('{');
    if(pos == string::npos){ cout << "{}"; return 0; }
    pos++;
    while(pos < input.size()){
        pos = input.find('"', pos);
        if(pos == string::npos) break;
        size_t end = input.find('"', pos+1);
        if(end == string::npos) break;
        string key = input.substr(pos+1, end-pos-1);
        pos = end+1;
        size_t br = input.find('[', pos);
        if(br == string::npos) break;
        size_t br2 = input.find(']', br);
        if(br2 == string::npos) break;
        string arr = input.substr(br+1, br2-br-1);
        pos = br2+1;
        vector<long long> nums;
        long long val=0; bool inNum=false;
        for(char c:arr){
            if(c>='0'&&c<='9'){val=val*10+(c-'0');inNum=true;}
            else{if(inNum)nums.push_back(val);val=0;inNum=false;}
        }
        if(inNum)nums.push_back(val);
        if(nums.size()==4) items.emplace_back(key,(int)nums[0],nums[1],nums[2],nums[3]);
    }

    int n=items.size();
    if(n==0){cout<<"{}";return 0;}

    const long long capM=20000000LL, capL=25000000LL;

    // Sort by value density descending
    sort(items.begin(),items.end(),[&](auto&a,auto&b){
        double wa=max((double)get<3>(a)/capM,(double)get<4>(a)/capL);
        double wb=max((double)get<3>(b)/capM,(double)get<4>(b)/capL);
        double da=(wa>1e-15)?(double)get<2>(a)/wa:1e30;
        double db=(wb>1e-15)?(double)get<2>(b)/wb:1e30;
        return da>db;
    });

    long long bestVal=0;
    vector<int> bestSol(n,0), curSol(n,0);
    bool timeUp=false;
    long long nc=0;

    function<void(int,long long,long long,long long)> solve=[&](int idx,long long rm,long long rl,long long cv){
        if(timeUp)return;
        if(idx==n){if(cv>bestVal){bestVal=cv;bestSol=curSol;}return;}
        if((++nc&0xFFFF)==0){auto now=chrono::steady_clock::now();if(chrono::duration_cast<chrono::milliseconds>(now-startTime).count()>900)timeUp=true;}
        if(timeUp)return;

        // Simple greedy UB
        double ub=(double)cv;
        double trm=rm,trl=rl;
        for(int i=idx;i<n;i++){
            double mxM=(get<3>(items[i])>0)?trm/get<3>(items[i]):1e18;
            double mxL=(get<4>(items[i])>0)?trl/get<4>(items[i]):1e18;
            double take=min({(double)get<1>(items[i]),mxM,mxL});
            if(take<0)take=0;
            ub+=take*get<2>(items[i]);
            trm-=take*get<3>(items[i]);
            trl-=take*get<4>(items[i]);
        }
        if(ub<=(double)bestVal+0.5)return;

        long long mxM=(get<3>(items[idx])>0)?rm/get<3>(items[idx]):(long long)get<1>(items[idx]);
        long long mxL=(get<4>(items[idx])>0)?rl/get<4>(items[idx]):(long long)get<1>(items[idx]);
        int maxTake=(int)min({(long long)get<1>(items[idx]),mxM,mxL});

        for(int k=maxTake;k>=0;k--){
            curSol[idx]=k;
            solve(idx+1,rm-(long long)k*get<3>(items[idx]),rl-(long long)k*get<4>(items[idx]),cv+(long long)k*get<2>(items[idx]));
            if(timeUp)return;
        }
        curSol[idx]=0;
    };

    solve(0,capM,capL,0);

    cout<<"{";
    bool first=true;
    for(int i=0;i<n;i++){
        if(bestSol[i]>0){
            if(!first)cout<<", ";
            cout<<"\""<<get<0>(items[i])<<"\": "<<bestSol[i];
            first=false;
        }
    }
    cout<<"}";
    return 0;
}
